// ============================================================
// Workflow Submit Port - actor terminal-result verdict boundary
// ============================================================

import type { TraceContext } from "../tracing/tracer.js";
import type { ToolCallId } from "./shared.js";

/**
* The single violation generated by the validator is designed to be directly entered into the tool_result for repair: one per line, including
* JSON path, expected and got.
 *
* The structure is consistent with Violation on the synthesis side of dynamic-workflow; the driver is responsible for converting the engine
* The Violation is mapped to this port as it is, and contracts do not rely on dynamic-workflow in reverse.
 */
export interface SubmitViolation {
/** JSON path to the location of the violation, in the form of `$`, `$.foo`, `$.items[0]`. */
  path: string;
/** A short description of the desired shape/value. */
  expected: string;
/** A short description of the actual value obtained. */
  got: string;
}

export interface SubmitResultRequest {
/** The tool call id within the actor subsession that initiated the submit_result call. */
  toolCallId: ToolCallId | string;
/** The original structured result submitted by the model (any JSON that has not been verified by this port). */
  result: unknown;
  trace: TraceContext;
}

/** The engine accepts this submission: the actor turn should terminate after the result is returned. */
export interface SubmitAccepted {
  accept: true;
}

/** The engine rejects this submission: Returns a list of violations for the model to fix and try again within the same session. */
export interface SubmitRejected {
  accept: false;
  violations: readonly SubmitViolation[];
}

export type SubmitVerdict = SubmitAccepted | SubmitRejected;

export interface WorkflowSubmitPort {
  /**
* Submit the actor's structured final state and wait for engine decision-making.
   *
* Unlike CoordinatorResponsePort, this **blocks** until the engine completes verification: the engine may be out of band
* Run multiple rounds of repair/budget determination, so resolve may take arbitrarily long. Cancellation is not expressed by this port - by abort
* To handle this tool call (abort), the driver will convert out-of-band ask cancellation into turn abort.
   *
* The routing identity (instance/actor/session) is bound by the port closure and cannot be overridden by the model.
   */
  respond(request: SubmitResultRequest): Promise<SubmitVerdict>;
}
